package com.lexorion.finance.observability;
import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import java.util.UUID;import org.slf4j.MDC;import org.springframework.core.Ordered;import org.springframework.core.annotation.Order;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;
@Component @Order(Ordered.HIGHEST_PRECEDENCE+1) public class CorrelationIdFilter extends OncePerRequestFilter{public static final String HEADER="X-Correlation-ID",MDC_KEY="correlationId";@Override protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String v=r.getHeader(HEADER),id=v!=null&&v.matches("[A-Za-z0-9._:-]{1,64}")?v:UUID.randomUUID().toString();s.setHeader(HEADER,id);MDC.put(MDC_KEY,id);try{c.doFilter(r,s);}finally{MDC.remove(MDC_KEY);}}}
